import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"ESC (PX4)","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-user-guide/setup_view/px4/esc.md","filePath":"en/qgc-user-guide/setup_view/px4/esc.md"}`),a={name:`en/qgc-user-guide/setup_view/px4/esc.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="esc-px4" tabindex="-1">ESC (PX4) <a class="header-anchor" href="#esc-px4" aria-label="Permalink to “ESC (PX4)”">​</a></h1><p>The ESC page calibrates ESCs that take a PWM signal and configures the DShot and DroneCAN ESC settings. It is designed for PX4 1.17 or later. Older firmware shows only the settings it has.</p><p>The page only shows settings the connected vehicle has, and only the groups that apply to its motor outputs. The output protocol (PWM, OneShot or DShot) and the per-channel output limits are set on the <a href="./actuators.html">Actuators</a> page. The choices, units and limits of each setting come from the vehicle&#39;s parameter metadata.</p><p>Settings that only take effect after the vehicle reboots are marked <em>Applies after reboot</em>. Once one is changed from the value it had when the page opened, the mark becomes a <em>Reboot required</em> warning. The page shows these marks instead of the reboot notice that QGroundControl shows elsewhere. Reboot from the main status indicator in the toolbar.</p><h2 id="calibration" tabindex="-1">Calibration <a class="header-anchor" href="#calibration" aria-label="Permalink to “Calibration”">​</a></h2><p>Calibration teaches ESCs that take a PWM signal the full throttle range of the flight controller. DShot and DroneCAN ESCs do not need it, so the section is hidden when every output group is set to DShot.</p><p>To calibrate:</p><ol><li>Remove the propellers.</li><li>Connect the vehicle to QGroundControl with USB only, with the battery disconnected.</li><li>Click <strong>Calibrate</strong>.</li><li>Connect the battery when the prompt asks for it, and wait for calibration to finish.</li></ol><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Never attempt ESC calibration with propellers fitted.</p><p>Motors should not spin during ESC calibration. However, if an ESC doesn&#39;t properly support the calibration sequence it will respond to the PWM input by running the motor at maximum speed.</p></div><h2 id="dshot" tabindex="-1">DShot <a class="header-anchor" href="#dshot" aria-label="Permalink to “DShot”">​</a></h2><p>These settings are shown while an output group is set to DShot.</p><ul><li><strong>Output</strong> — the minimum output, which should be high enough that the motors keep spinning while armed. <em>3D mode</em> lets the motors spin in both directions. It needs ESCs set to 3D mode and the minimum output set to 0. The two deadband settings are shown while 3D mode is on.</li><li><strong>Telemetry</strong> — the data the ESCs return over the DShot signal wire. PX4 1.17 has <em>Bidirectional DShot</em>, which returns RPM and needs ESCs that support it, such as BLHeli32. Newer PX4 has <em>Extended DShot telemetry</em>, which also returns ESC temperature, voltage and current. <em>ESC firmware</em> lets the flight controller read ESC settings over the telemetry wire. The motor pole count turns the ESC&#39;s electrical RPM into motor RPM: PX4 1.17 has one setting for all motors, newer PX4 has one per motor. Telemetry over a separate serial wire is set on the <a href="./ports.html">Ports</a> page.</li></ul><h2 id="dronecan" tabindex="-1">DroneCAN <a class="header-anchor" href="#dronecan" aria-label="Permalink to “DroneCAN”">​</a></h2><p><strong>ESC messages</strong> chooses which CAN interfaces carry ESC messages. They are sent often at high priority, so use only the interfaces which have ESCs on them.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};